const text = $json.textPlain || $json.snippet || '';
return [{ json: {
  inquiry_id: $json.id,
  sender_name: $json.from?.value?.[0]?.name || '',
  sender_email: $json.from?.value?.[0]?.address || $json.from || '',
  subject: $json.subject || '',
  message: text.slice(0, 12000),
  received_at: $json.date || new Date().toISOString()
}}];

const source = $json.output || $json.text || '{}';
let evaluation; try { evaluation = typeof source === 'string' ? JSON.parse(source.replace(/```json|```/g, '')) : source; } catch { evaluation = { inquiry_type: 'other', urgency: 'normal', lead_score: 0, confidence: 0, missing_information: ['Could not parse AI output'], recommended_next_action: 'human_review' }; }
const original = $('Normalize Client Inquiry').first().json;
const review_required = evaluation.confidence < 0.75 || evaluation.lead_score < 45 || evaluation.recommended_next_action === 'human_review';
return [{ json: { ...original, ...evaluation, review_required, stage: review_required ? 'needs_review' : 'qualified' } }];

